// Node: Workflow Config   ([SPL] Simpro -> HubSpot (Real Time))
// Single source of truth for this workflow: edit values HERE only.
// It also turns the Simpro webhook event into "which record type is this and where do I fetch it".
// An event for a record type we do not handle ends here on purpose (no item out).
const CONFIG = {
  simproBaseUrl: 'https://spl.simprosuite.com/api/v1.0',
  hubspotApiBase: 'https://api.hubapi.com',
  // --- Test-record rule (do not loosen without asking SPL) ---
  // A record is a test record when EITHER its name starts with testNamePrefix OR its email (if it has one) has one
  // of testEmailDomains. Both checks are case-insensitive; the domain must match exactly.
  testNamePrefix: 'HSTEST-',
  testEmailDomains: ['aniccadigital.io', 'spl.com.au'],
  // --- HubSpot object paths, unique Simpro-ID properties and association API names ---
  objects: {
    site: { path: 'crm/objects/2026-09/0-420', idProperty: 'simpro_site_id', assoc: '0-420' },
    company: { path: 'crm/objects/2026-09/companies', idProperty: 'simpro_customer_id', assoc: 'companies' },
    contact: { path: 'crm/objects/2026-09/contacts', idProperty: 'simpro_contact_id', assoc: 'contacts' },
    quote: { path: 'crm/objects/2026-09/deals', idProperty: 'simpro_quote_id', assoc: 'deals' }, // a quote is a deal
    job: { path: 'crm/objects/2026-09/deals', idProperty: 'simpro_job_id', assoc: 'deals' },
  },
  // --- Custom association labels (HubSpot user-defined) ---
  decisionMaker: [{ associationCategory: 'USER_DEFINED', associationTypeId: 10 }], // primary contact on a quote/job deal
  quoteJob: [{ associationCategory: 'USER_DEFINED', associationTypeId: 11 }], // label "Job" on the quote, "Quote" on the job; quote is the FROM side
  // --- Quote deals ---
  quote: {
    pipeline: 'default',
    stageToBeCompleted: '3788243436', // Quote to be completed / Quote overdue
    stageWon: 'closedwon',
    stageLost: 'closedlost',
    stageDefault: '3788243437',
    cfTenderNumber: 35, // Simpro custom field IDs
    cfTenderStatus: 36,
    cfVertical: 49,
  },
  // --- Job deals ---
  job: {
    pipeline: '2172954069',
    stagePending: '3783391728',
    stageProgress: '3783391729',
    stageComplete: '3783391730',
    stageArchived: '3783391734',
    stageDefault: '3783391728',
  },
};

const body = $input.first().json.body ?? {};
const r = body.reference ?? {};
const ROUTES = {
  'Site': { type: 'site', id: r.siteID, path: 'companies/' + r.companyID + '/sites/' + r.siteID },
  'Company customer': { type: 'company', id: r.customerID, path: 'companies/0/customers/companies/' + r.customerID },
  'Contact': { type: 'contact', id: r.contactID, path: 'companies/0/contacts/' + r.contactID },
  'Quote': { type: 'quote', id: r.quoteID, path: 'companies/' + r.companyID + '/quotes/' + r.quoteID },
  'Job': { type: 'job', id: r.jobID, path: 'companies/' + r.companyID + '/jobs/' + r.jobID },
};
const route = ROUTES[body.name];
if (!route || route.id === undefined || route.id === null) return []; // not a record type we handle

return [{ json: {
  ...CONFIG,
  type: route.type,
  simproId: String(route.id),
  recordUrl: CONFIG.simproBaseUrl + '/' + route.path,
  event: { name: body.name, action: body.action ?? null },
} }];

// Node: Select Test Record   ([SPL] Simpro -> HubSpot (Real Time))
// Applies the test-record rule (name starts with HSTEST- OR email domain is a test domain) to the Simpro
// record that was just fetched. A record that is not a test record ends here on purpose (no item out), so
// nothing else is called. Otherwise builds the HubSpot search that
// answers "is this record already in HubSpot?" (a contact is also matched on email, see Check Is New).
const cfg = $('Workflow Config').first().json;
const rec = $input.first().json;

// Name: Name (sites, quotes, jobs), CompanyName (companies), GivenName + FamilyName (contacts)
const name = String(rec.Name ?? rec.CompanyName ?? [rec.GivenName, rec.FamilyName].filter(Boolean).join(' ')).trim().toLowerCase();
const nameMatches = name.startsWith(String(cfg.testNamePrefix).toLowerCase());
// Email: the record's own Email (contacts, companies). Records without one (sites, quotes, jobs) match on name only.
const email = String(rec.Email ?? '').trim().toLowerCase();
const domain = email.includes('@') ? email.split('@').pop() : '';
const domainMatches = domain !== '' && cfg.testEmailDomains.map(d => String(d).trim().toLowerCase()).includes(domain);
const isTest = nameMatches || domainMatches;
if (!isTest) return [];

const o = cfg.objects[cfg.type];
const filterGroups = [{ filters: [{ propertyName: o.idProperty, operator: 'EQ', value: String(rec.ID) }] }];
const properties = [o.idProperty];
if (cfg.type === 'contact') {
  properties.push('email');
  if (email) filterGroups.push({ filters: [{ propertyName: 'email', operator: 'EQ', value: email }] });
}
return [{ json: { url: cfg.hubspotApiBase + '/' + o.path + '/search', body: { filterGroups, properties, limit: 5 } } }];

// Node: Check Is New   ([SPL] Simpro -> HubSpot (Real Time))
// Real Time only CREATES. A record that is already in HubSpot ends here on purpose (no item out): updates are
// the job of the 30-minute sync workflows. A contact needs its email AND Simpro ID to match: a NEW Simpro contact
// whose email already belongs to another HubSpot contact is not created or merged, the run fails loudly.
const cfg = $('Workflow Config').first().json;
const rec = $('Get Simpro Record').first().json;
const hits = $input.first().json.results;
if (!Array.isArray(hits)) throw new Error('Unexpected HubSpot search response (no results array): ' + JSON.stringify($input.first().json).slice(0, 200));
const idProperty = cfg.objects[cfg.type].idProperty;

if (cfg.type !== 'contact') {
  return hits.length ? [] : [{ json: { isNew: true } }];
}
if (hits.some(h => String(h.properties && h.properties[idProperty]) === String(rec.ID))) return []; // already there
if (hits.length) {
  const other = hits[0];
  throw new Error('Contact ' + rec.ID + ' (' + rec.Email + ') was NOT created: that email already belongs to HubSpot contact '
    + other.id + ' (simpro_contact_id: ' + ((other.properties && other.properties[idProperty]) || 'none')
    + '). Email and Simpro ID must match - resolve it in HubSpot, then re-run.');
}
return [{ json: { isNew: true } }];

// Node: Build Create Request   ([SPL] Simpro -> HubSpot (Real Time))
// Builds the ONE HubSpot create call for this record (same field mapping as the old Upsert sub-workflows and
// the batch sync workflows) and the list of related records it should be linked to (`related`).
//   related[].ids      Simpro IDs of the related records
//   related[].primary  (labelled links only) the Simpro ID that gets the label; the other ids get NO label
//   related[].label    HubSpot association type(s) used for the labelled link
//   related[].quoteIsFrom  the related record is the FROM side of the labelled link (Quote -> Job)
const cfg = $('Workflow Config').first().json;
const rec = $('Get Simpro Record').first().json;
const blank = (v) => v === null || v === undefined || v === '' || v === 'null';
const keep = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => !blank(v)).map(([k, v]) => [k, String(v)]));
const ids = (arr) => [...new Set(arr.filter(v => !blank(v)).map(String))];
const day = (iso) => iso ? DateTime.fromISO(iso, { zone: 'utc' }).startOf('day').toMillis() : '';
const o = cfg.objects[cfg.type];

// SPL Users data table (Simpro_ID -> HubSpot_ID), only used by quotes and jobs
const users = {};
for (const row of $input.all()) {
  const j = row.json ?? {};
  if (j.Simpro_ID !== undefined && j.Simpro_ID !== null) users[String(j.Simpro_ID)] = j.HubSpot_ID;
}

let properties;
let related;
switch (cfg.type) {
  case 'company':
    properties = keep({
      simpro_customer_id: rec.ID, name: rec.CompanyName,
      address: rec.Address?.Address, city: rec.Address?.City, state: rec.Address?.State, zip: rec.Address?.PostalCode, country: rec.Address?.Country,
      billing_address: rec.BillingAddress?.Address, billing_city: rec.BillingAddress?.City, billing_state: rec.BillingAddress?.State,
      billing_zip: rec.BillingAddress?.PostalCode, billing_country: rec.BillingAddress?.Country,
      phone: rec.Phone, website: rec.Website, email: rec.Email, abn: rec.EIN,
    });
    related = [
      { key: 'contact', toType: 'contact', ids: ids((rec.Contacts ?? []).map(c => c.ID)) },
      { key: 'site', toType: 'site', ids: ids((rec.Sites ?? []).map(s => s.ID)) },
    ];
    break;
  case 'site':
    properties = keep({
      simpro_site_id: rec.ID, hs_name: rec.Name,
      hs_address_1: rec.Address?.Address, hs_city: rec.Address?.City, hs_state_province: rec.Address?.State, hs_zip: rec.Address?.PostalCode,
      country: rec.Address?.Country, zone: rec.Zone?.ID,
      billing_address: rec.BillingAddress?.Address, billing_city: rec.BillingAddress?.City, billing_state: rec.BillingAddress?.State,
      billing_postal_code: rec.BillingAddress?.PostalCode,
    });
    related = [
      { key: 'company', toType: 'company', ids: ids((rec.Customers ?? []).map(c => c.ID)) },
      { key: 'primaryContact', toType: 'contact', ids: ids([rec.PrimaryContact?.Contact?.ID]) },
    ];
    break;
  case 'contact':
    properties = keep({
      simpro_contact_id: rec.ID, email: String(rec.Email ?? '').trim(),
      firstname: rec.GivenName, lastname: rec.FamilyName, jobtitle: rec.Position, phone: rec.WorkPhone, salutation: rec.Title, department: rec.Department,
    });
    related = [
      { key: 'company', toType: 'company', ids: ids((rec.Customers ?? []).map(c => c.ID)) },
      { key: 'site', toType: 'site', ids: ids((rec.Sites ?? []).map(s => s.ID)) },
    ];
    break;
  case 'quote': {
    const d = cfg.quote;
    const customField = (id) => (rec.CustomFields ?? []).find(f => f.CustomField?.ID === Number(id))?.Value ?? '';
    const stages = { 'quote to be completed': d.stageToBeCompleted, 'quote overdue': d.stageToBeCompleted, 'quote won': d.stageWon, 'quote lost': d.stageLost };
    const status = String(rec.Status?.Name ?? '').trim().toLowerCase();
    // NOTE (carried over from [SPL] Upsert Quote in HubSpot): owner AND project manager are both looked up with ProjectManager.ID
    const owner = users[String(rec.ProjectManager?.ID)];
    properties = {
      dealname: rec.Name, amount: rec.Total?.ExTax, description: rec.Notes ?? '', pipeline: d.pipeline,
      dealstage: stages[status] ?? d.stageDefault, hubspot_owner_id: owner, project_manager: owner,
      simpro_quote_id: String(rec.ID), approved_date: day(rec.DateApproved), due_date: day(rec.DueDate),
      orderno: rec.OrderNo ?? '', validity: rec.ValidityDays ?? '', simpro_description: rec.Description ?? '',
      project_tags: (rec.Tags ?? []).map(tag => tag.ID).join(';'),
      tender_number: customField(d.cfTenderNumber), tender_status: customField(d.cfTenderStatus),
      quote_type: rec.Type ?? '', vertical: customField(d.cfVertical),
    };
    related = [
      { key: 'site', toType: 'site', ids: ids([rec.Site?.ID]) },
      { key: 'contact', toType: 'contact', ids: ids([rec.CustomerContact?.ID, ...(rec.AdditionalContacts ?? []).map(c => c.ID)]), primary: blank(rec.CustomerContact?.ID) ? null : String(rec.CustomerContact.ID), label: cfg.decisionMaker },
      { key: 'company', toType: 'company', ids: ids([rec.Customer?.ID]) },
    ];
    break;
  }
  case 'job': {
    const d = cfg.job;
    const stages = { pending: d.stagePending, progress: d.stageProgress, complete: d.stageComplete, archived: d.stageArchived };
    const stageKey = String(rec.Stage ?? '').trim().toLowerCase();
    properties = {
      dealname: rec.Name, amount: rec.Total?.ExTax, description: rec.Notes ?? '', pipeline: d.pipeline,
      dealstage: stages[stageKey] ?? d.stageDefault,
      hubspot_owner_id: users[String(rec.Salesperson?.ID)], project_manager: users[String(rec.ProjectManager?.ID)],
      simpro_job_id: String(rec.ID), approved_date: day(rec.DateApproved), due_date: day(rec.DueDate),
      orderno: rec.OrderNo ?? '', simpro_description: rec.Description ?? '',
      project_tags: (rec.Tags ?? []).map(tag => tag.ID).join(';'), job_type: rec.Type ?? '',
    };
    related = [
      { key: 'site', toType: 'site', ids: ids([rec.Site?.ID]) },
      { key: 'contact', toType: 'contact', ids: ids([rec.CustomerContact?.ID, ...(rec.AdditionalContacts ?? []).map(c => c.ID)]), primary: blank(rec.CustomerContact?.ID) ? null : String(rec.CustomerContact.ID), label: cfg.decisionMaker },
      { key: 'company', toType: 'company', ids: ids([rec.Customer?.ID]) },
      // the quote this job was converted from (a quote is a deal): Simpro ConvertedFromQuote.ID, or ConvertedFrom when its Type is Quote
      { key: 'quote', toType: 'quote', ids: ids([rec.ConvertedFromQuote?.ID ?? (rec.ConvertedFrom?.Type === 'Quote' ? rec.ConvertedFrom.ID : undefined)]), label: cfg.quoteJob, quoteIsFrom: true },
    ];
    break;
  }
  default:
    throw new Error('Unhandled record type: ' + cfg.type);
}

return [{ json: {
  recordType: cfg.type,
  fromObject: o.assoc,
  url: cfg.hubspotApiBase + '/' + o.path,
  body: { properties },
  related: related.filter(x => x.ids.length > 0),
} }];

// Node: Build Related Lookups   ([SPL] Simpro -> HubSpot (Real Time))
// The record was just CREATED in HubSpot. Ask HubSpot, in one batch read per related type, which of the related
// Simpro records already exist (by their unique Simpro ID property). Related records that are not in HubSpot are
// NOT created here: they are skipped. No items out = nothing to link, the branch ends on purpose.
const cfg = $('Workflow Config').first().json;
const spec = $('Build Create Request').first().json;
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));

const needed = {}; // toType -> Set(simpro ids)
for (const rel of spec.related) {
  for (const id of rel.ids) (needed[rel.toType] = needed[rel.toType] ?? new Set()).add(id);
}
const requests = [];
for (const [toType, set] of Object.entries(needed)) {
  const o = cfg.objects[toType];
  chunk([...set], 100).forEach((part, n) => requests.push({
    url: cfg.hubspotApiBase + '/' + o.path + '/batch/read',
    body: { idProperty: o.idProperty, properties: [o.idProperty], inputs: part.map(id => ({ id })) },
    meta: { toType, idProperty: o.idProperty, batch: n + 1 },
  }));
}
return requests.map(r => ({ json: r }));

// Node: Build Associations   ([SPL] Simpro -> HubSpot (Real Time))
// Links the newly created record to the related records that already exist in HubSpot. Related records that
// are not in HubSpot are skipped and listed (`skipped` on the items and `skippedLinks` in the execution's custom
// data, so it stays visible even when nothing is left to link). Nothing is ever removed or updated.
//   plain links     -> batch associate (default, NO label)
//   labelled links  -> batch create with the label: the primary contact of a quote/job gets "Decision Maker";
//                      a job's quote link uses the Job/Quote label with the quote as the FROM side.
const cfg = $('Workflow Config').first().json;
const spec = $('Build Create Request').first().json;
const fromId = String($('Create Record in HubSpot').first().json.id);
const lookups = $('Build Related Lookups').all(); // the requests, in the order they were sent
const base = cfg.hubspotApiBase + '/crm/v4/associations/';

const found = {}; // toType -> { simproId: hubspotId }
$input.all().forEach((item, k) => {
  const idx = (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;
  const meta = lookups[idx].json.meta;
  const r = item.json ?? {};
  if (r.statusCode === 404) return; // none of this batch exists in HubSpot
  if (r.statusCode !== 200 && r.statusCode !== 207) {
    throw new Error('HubSpot lookup of related ' + meta.toType + ' failed (HTTP ' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 300));
  }
  found[meta.toType] = found[meta.toType] ?? {};
  for (const x of ((r.body && r.body.results) || [])) {
    const sid = x.properties ? x.properties[meta.idProperty] : undefined;
    if (sid !== undefined && sid !== null) found[meta.toType][String(sid)] = String(x.id);
  }
});

const skipped = [];
const requests = [];
for (const rel of spec.related) {
  const toObject = cfg.objects[rel.toType].assoc;
  const plain = [];
  const labelled = [];
  for (const id of rel.ids) {
    const hs = found[rel.toType] ? found[rel.toType][id] : undefined;
    if (!hs) { skipped.push({ link: rel.key, relatedSimproId: id, reason: 'not in HubSpot - link skipped' }); continue; }
    if (rel.quoteIsFrom) labelled.push({ from: { id: hs }, to: { id: fromId }, types: rel.label });
    else if (rel.label && id === rel.primary) labelled.push({ from: { id: fromId }, to: { id: hs }, types: rel.label });
    else plain.push({ from: { id: fromId }, to: { id: hs } });
  }
  if (plain.length) requests.push({ url: base + spec.fromObject + '/' + toObject + '/batch/associate/default', body: { inputs: plain }, meta: { link: rel.key, kind: 'plain', count: plain.length } });
  if (labelled.length) {
    const pair = rel.quoteIsFrom ? 'deals/deals' : spec.fromObject + '/' + toObject;
    requests.push({ url: base + pair + '/batch/create', body: { inputs: labelled }, meta: { link: rel.key, kind: 'labelled', count: labelled.length } });
  }
}
if (skipped.length) $execution.customData.set('skippedLinks', skipped.map(s => s.link + ':' + s.relatedSimproId).join(', ').slice(0, 250));
return requests.map(r => ({ json: { ...r, skipped } }));

// Node: Check Association Results   ([SPL] Simpro -> HubSpot (Real Time))
// Batch associate/create answer 2xx even when single links are rejected (for example a label limit), so inspect
// every response and fail loudly.
const errors = [];
for (const item of $input.all()) {
  const b = item.json ?? {};
  const errs = Array.isArray(b.errors) ? b.errors : [];
  if (errs.length || Number(b.numErrors) > 0) {
    errors.push(...errs.map(e => (e && (e.message || e.category)) || JSON.stringify(e)));
    if (!errs.length) errors.push('numErrors=' + b.numErrors);
  }
}
if (errors.length) throw new Error('HubSpot rejected part of the associations: ' + errors.slice(0, 5).join(' | '));
return [{ json: { ok: true, calls: $input.all().length } }];

// Node: Build Section Request   ([SPL] Simpro -> HubSpot (Real Time))
// Quotes and jobs only: ask Simpro for the sections of the new quote/job (cost centers hang off sections).
// Any other record type ends here on purpose (no item out).
const cfg = $('Workflow Config').first().json;
if (cfg.type !== 'quote' && cfg.type !== 'job') return [];
return [{ json: { url: cfg.recordUrl + '/sections/?pageSize=250' } }];

// Node: Build Cost Center Requests   ([SPL] Simpro -> HubSpot (Real Time))
// One request per Simpro section (this node only runs when there is at least one section).
const cfg = $('Workflow Config').first().json;
const requests = $input.all()
  .map(i => i.json)
  .filter(s => s && s.ID !== undefined && s.ID !== null)
  .map(s => ({ json: { url: cfg.recordUrl + '/sections/' + s.ID + '/costCenters/?pageSize=250' } }));
return requests; // none = no usable section, the branch ends on purpose

// Node: Build Line Items   ([SPL] Simpro -> HubSpot (Real Time))
// One HubSpot line item per Simpro cost center, linked to the new deal. Same fields as the old sub-workflows,
// but the price is the GST-EXCLUSIVE total (Total.ExTax). Batches of 100. No cost centers = the branch ends.
const cfg = $('Workflow Config').first().json;
const dealId = String($('Create Record in HubSpot').first().json.id);
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));

const costCenters = $input.all().map(i => i.json).filter(c => c && c.ID);
const inputs = costCenters.map(c => ({
  properties: {
    name: c.Name ?? c.CostCenter.Name,
    quantity: '1',
    price: c.Total.ExTax.toString(),
    cost_centre: c.CostCenter.ID.toString(),
    simpro_id: c.ID.toString(),
  },
  associations: [{ to: { id: dealId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 20 }] }],
}));
return chunk(inputs, 100).map((part, n) => ({
  json: { url: cfg.hubspotApiBase + '/crm/objects/2026-09/line_items/batch/create', body: { inputs: part }, meta: { batch: n + 1, count: part.length } },
}));

// Node: Check Line Item Results   ([SPL] Simpro -> HubSpot (Real Time))
// The batch create answers 2xx even when single line items are rejected, so inspect it and guard the count.
const sent = $('Build Line Items').all().reduce((n, i) => n + (i.json.meta ? i.json.meta.count : 0), 0);
const errors = [];
let created = 0;
for (const item of $input.all()) {
  const b = item.json ?? {};
  const errs = Array.isArray(b.errors) ? b.errors : [];
  if (errs.length || Number(b.numErrors) > 0) {
    errors.push(...errs.map(e => (e && (e.message || e.category)) || JSON.stringify(e)));
    if (!errs.length) errors.push('numErrors=' + b.numErrors);
  }
  created += Array.isArray(b.results) ? b.results.length : 0;
}
if (errors.length) throw new Error('HubSpot rejected part of the line items: ' + errors.slice(0, 5).join(' | '));
if (created !== sent) throw new Error('HubSpot created ' + created + ' line item(s) but ' + sent + ' were sent.');
return [{ json: { lineItems: created } }];
